import{_ as i}from"./chunks/ArticleMetadata.1_--bNMz.js";import{_ as t,D as l,o as d,c as r,I as p,w as u,k as s,a as h,R as m,b as _,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const A=JSON.parse('{"title":"学习开源项目栏目设计","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-09-20-open-source-learning-design.md","filePath":"superpowers/specs/2026-09-20-open-source-learning-design.md","lastUpdated":1789909212000}'),b={name:"superpowers/specs/2026-09-20-open-source-learning-design.md"},x=s("h1",{id:"学习开源项目栏目设计",tabindex:"-1"},[h("学习开源项目栏目设计 "),s("a",{class:"header-anchor",href:"#学习开源项目栏目设计","aria-label":'Permalink to "学习开源项目栏目设计"'},"​")],-1),k=m(`<h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>在现有个人知识库中新增一级栏目“学习开源项目”，用于持续记录开源项目的源码阅读、架构理解和可验证实验。栏目应与现有 VitePress 内容体系自然融合，在 GitHub Pages 上保持纯静态部署，并通过克制的苹果式视觉语言提升全站质感。</p><h2 id="约束与成功标准" tabindex="-1">约束与成功标准 <a class="header-anchor" href="#约束与成功标准" aria-label="Permalink to &quot;约束与成功标准&quot;">​</a></h2><ul><li>不增加服务端、运行时 GitHub API、外部字体或大型前端依赖。</li><li>内容仍以 Markdown 为唯一事实来源；新增项目不需要修改 Vue 组件。</li><li><code>/open-source/</code>、项目首页和学习笔记支持直接刷新与静态构建。</li><li>浅色、深色、键盘操作和移动端均可用；动效尊重 <code>prefers-reduced-motion</code>。</li><li><code>pnpm build</code> 成功，且现有内容、CNAME 与部署方式不变。</li></ul><h2 id="信息架构" tabindex="-1">信息架构 <a class="header-anchor" href="#信息架构" aria-label="Permalink to &quot;信息架构&quot;">​</a></h2><p>导航在“项目文档”之后新增“学习开源项目”，链接到 <code>/open-source/</code>。同时将“首页”链接修正为真实首页 <code>/</code>。</p><p>内容目录采用以下约定：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span>docs/open-source/</span></span>
<span class="line"><span>├─ index.md</span></span>
<span class="line"><span>└─ 01-RuoYi/</span></span>
<span class="line"><span>   ├─ index.md</span></span>
<span class="line"><span>   ├─ 01-项目概览.md</span></span>
<span class="line"><span>   ├─ 02-目录与模块.md</span></span>
<span class="line"><span>   └─ 03-启动链路.md</span></span></code></pre></div><p>项目目录的 <code>index.md</code> 通过 frontmatter 声明 <code>projectName</code>、<code>repo</code>、<code>summary</code>、<code>stack</code>、<code>status</code> 和 <code>order</code>。<code>status</code> 只允许 <code>learning</code>、<code>completed</code>、<code>paused</code>，分别显示“学习中”“已完成”“暂停”。笔记数量由构建期扫描项目目录内除 <code>index.md</code> 之外的 Markdown 文件得到。</p><p>首个项目为 RuoYi，提供项目概览、目录与模块、启动链路三篇起始笔记，内容定位为可继续扩展的学习骨架，不虚构实时仓库指标。</p><h2 id="组件与数据流" tabindex="-1">组件与数据流 <a class="header-anchor" href="#组件与数据流" aria-label="Permalink to &quot;组件与数据流&quot;">​</a></h2><p><code>open-source.data.ts</code> 在构建期扫描 <code>docs/open-source/*/index.md</code>，验证并规范化 frontmatter，计算每个项目的笔记数和站内链接，然后按 <code>order</code> 与目录名稳定排序。无效状态回退为 <code>paused</code>，缺失可选字段回退为空值，确保单个项目元数据不完整时仍可构建。</p><p><code>OpenSourceProjects.vue</code> 仅接收构建期生成的数据，渲染语义化项目卡片。整张卡片使用真实链接，仓库链接独立提供可辨识标签；卡片展示项目名、摘要、状态、技术栈和笔记数量，不请求任何运行时数据。</p><p><code>docs/open-source/index.md</code> 使用自定义首页布局承载栏目说明与组件。项目内页继续使用 VitePress 默认文档布局，并由专用侧栏按项目目录分组。</p><h2 id="视觉设计" tabindex="-1">视觉设计 <a class="header-anchor" href="#视觉设计" aria-label="Permalink to &quot;视觉设计&quot;">​</a></h2><ul><li>系统字体栈；主品牌色使用 <code>#0071e3</code>，正文使用高对比中性色。</li><li>页面背景为浅灰白，内容卡为纯白/半透明面板，圆角 18–24px、细边框和克制阴影。</li><li>顶部导航采用半透明背景与 <code>backdrop-filter</code>，并提供纯色回退。</li><li>首页 Hero 精简文案，新增“学习开源项目”主要入口；功能区调整为更清晰的四个方向。</li><li>栏目卡片在手机一列、平板两列、桌面最多三列；悬停只做轻微位移和阴影变化。</li><li>深色模式使用独立表面色、边框与阴影变量，不简单反色。</li></ul><h2 id="无障碍与降级" tabindex="-1">无障碍与降级 <a class="header-anchor" href="#无障碍与降级" aria-label="Permalink to &quot;无障碍与降级&quot;">​</a></h2><ul><li>所有主要导航与卡片均使用原生链接，提供清晰的 <code>:focus-visible</code>。</li><li>触控目标至少 44px，长标题、技术栈和路径允许换行。</li><li>状态同时使用文字与样式表达，不只依赖颜色。</li><li><code>prefers-reduced-motion: reduce</code> 时关闭非必要过渡和位移。</li><li>不支持 <code>backdrop-filter</code> 时保留不透明导航背景。</li></ul><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><ul><li>构建期数据逻辑使用 Node 内置测试验证排序、状态映射、笔记计数和缺失字段回退。</li><li>运行完整 <code>pnpm build</code> 验证 SSR、路由、frontmatter 与静态输出。</li><li>检查构建产物包含 <code>/open-source/</code>、RuoYi 首页和三篇笔记。</li><li>通过浏览器检查 375px、768px、1440px，以及浅色/深色和键盘焦点状态。</li></ul>`,20);function g(e,P,q,v,C,N){const n=i,c=l("ClientOnly");return d(),r("div",null,[x,p(c,null,{default:u(()=>{var a,o;return[(((a=e.$frontmatter)==null?void 0:a.aside)??!0)&&(((o=e.$frontmatter)==null?void 0:o.showArticleMetadata)??!0)?(d(),_(n,{key:0,article:e.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),k])}const T=t(b,[["render",g]]);export{A as __pageData,T as default};
